208	type LegacyHomeCandidate = { fingerprint: string; root: string };
209	
210	async function listSameGatewayLegacyHomes(params: {
211	  managedBase: string;
212	  newRoot: string;
213	  baseUrl: string;
214	}): Promise<LegacyHomeCandidate[]> {
215	  let dirents: Array<{ name: string; isDirectory(): boolean }>;
216	  try {
217	    dirents = await fs.readdir(params.managedBase, { withFileTypes: true });
218	  } catch {
219	    return [];
220	  }
221	
222	  const newName = path.basename(params.newRoot);
223	  const hits: LegacyHomeCandidate[] = [];
224	  for (const dirent of dirents) {
225	    if (!dirent.isDirectory()) continue;
226	    const name = dirent.name;
227	    if (!LEGACY_HOME_FINGERPRINT_RE.test(name) || name === newName) continue;
228	    const root = path.join(params.managedBase, name);
229	    if (!(await pathIsDirectory(path.join(root, "sessions")))) continue;
230	    let toml: string;
231	    try {
232	      toml = await fs.readFile(path.join(root, "config.toml"), "utf8");
233	    } catch {
234	      continue;
235	    }
236	    const match = MODELS_BASE_URL_RE.exec(toml);
237	    if (!match || match[1] !== params.baseUrl) continue;
238	    hits.push({ fingerprint: name, root });
239	  }
240	  return hits;
241	}
