243	async function sortByGrokDbMtimeDesc(
244	  candidates: LegacyHomeCandidate[],
245	): Promise<LegacyHomeCandidate[]> {
246	  const withMtime = await Promise.all(
247	    candidates.map(async (candidate) => {
248	      let mtime = Number.NEGATIVE_INFINITY;
249	      try {
250	        mtime = (await fs.stat(path.join(candidate.root, "grok.db"))).mtimeMs;
251	      } catch {
252	        // no grok.db → last
253	      }
254	      return { ...candidate, mtime };
255	    }),
256	  );
257	  withMtime.sort((a, b) => b.mtime - a.mtime);
258	  return withMtime;
259	}
