261	/**
262	 * Copy pre-fix managed GROK_HOMEs (fingerprint included modelId) into the
263	 * gateway-only home. Enumerate every sibling home on the same gateway rather
264	 * than hashing the current config.model: after a UI model switch, config.model
265	 * is already the new id, so the single computed legacy path is empty while
266	 * sessions still sit under the previous model's fingerprint.
267	 *
268	 * Copy, not move: keep legacy dirs as rollback. Sessions land via staging +
269	 * rename so a crash cannot leave a half-copied newRoot/sessions (which would
270	 * then skip retry forever). Sidecars (grok.db etc.) stage as
271	 * `<name>.migrating-<pid>` and only rename into place after sessions exist:
272	 * writing them to final names first would leave an orphan grok.db if a later
273	 * step fails, and the idempotency check only looks at sessions/, so a retry
274	 * would mix that leftover db with a freshly copied sessions tree. Sidecar
275	 * ENOENT is optional (wal/shm); any other error while staging sidecars
276	 * aborts so we do not keep a mismatched grok.db.
277	 *
278	 * Returns true when a copy happened. Failure is logged and returns false so
279	 * openSession can continue — empty-home fallback is the pre-fix behavior.
280	 */
281	export async function migrateLegacyGrokHomes(params: {
282	  managedBase: string;
283	  newRoot: string;
284	  baseUrl: string;
285	  logger: Logger;
286	}): Promise<boolean> {
287	  const destSessions = path.join(params.newRoot, "sessions");
288	  if (await pathIsDirectory(destSessions)) {
289	    return false;
290	  }
291	
292	  const staging = path.join(params.newRoot, `sessions.migrating-${process.pid}`);
293	  const sidecarTmps: string[] = [];
294	  const rmSidecarTmps = async () => {
295	    await Promise.all(sidecarTmps.map((tmp) => fs.rm(tmp, { force: true }).catch(() => undefined)));
296	  };
297	  try {
298	    const candidates = await listSameGatewayLegacyHomes(params);
299	    if (candidates.length === 0) {
300	      return false;
301	    }
302	    const sorted = await sortByGrokDbMtimeDesc(candidates);
303	    const primary = sorted[0];
304	    if (!primary) {
305	      return false;
306	    }
307	
308	    await fs.rm(staging, { recursive: true, force: true });
309	    await fs.cp(path.join(primary.root, "sessions"), staging, {
310	      recursive: true,
311	    });
312	    for (const other of sorted.slice(1)) {
313	      await fs.cp(path.join(other.root, "sessions"), staging, {
314	        recursive: true,
315	        force: false,
316	      });
317	    }
318	
319	    const sidecarDestByTmp = new Map<string, string>();
320	    for (const name of LEGACY_GROK_HOME_FILES) {
321	      const tmp = path.join(params.newRoot, `${name}.migrating-${process.pid}`);
322	      try {
323	        // copyFile (not recursive cp): sidecars are files; a directory named
324	        // grok.db must fail (EISDIR) rather than silently land as a tree.
325	        await fs.copyFile(path.join(primary.root, name), tmp);
326	        sidecarTmps.push(tmp);
327	        sidecarDestByTmp.set(tmp, path.join(params.newRoot, name));
328	      } catch (err) {
329	        // wal/shm are optional; anything else (EISDIR, EACCES) is a real failure.
330	        if ((err as NodeJS.ErrnoException).code === "ENOENT") continue;
331	        throw err;
332	      }
333	    }
334	
335	    try {
336	      await fs.rename(staging, destSessions);
337	    } catch (err) {
338	      const code = (err as NodeJS.ErrnoException).code;
339	      if (code === "ENOTEMPTY" || code === "EEXIST") {
340	        await fs.rm(staging, { recursive: true, force: true });
341	        await rmSidecarTmps();
342	        return false;
343	      }
344	      throw err;
345	    }
346	
347	    for (const tmp of sidecarTmps) {
348	      const dest = sidecarDestByTmp.get(tmp);
349	      if (!dest) continue;
350	      try {
351	        await fs.rename(tmp, dest);
352	      } catch (err) {
353	        // Sessions already landed; missing shm/wal is sqlite-recoverable.
354	        params.logger.warn(
355	          { err, from: tmp, to: dest },
356	          "Legacy GROK_HOME sidecar rename failed after sessions landed",
357	        );
358	        await fs.rm(tmp, { force: true }).catch(() => undefined);
359	      }
360	    }
361	
362	    params.logger.info(
363	      {
364	        from: sorted.map((c) => c.fingerprint),
365	        to: path.basename(params.newRoot),
366	        primary: primary.fingerprint,
367	      },
368	      "Migrated legacy managed GROK_HOME",
369	    );
370	    return true;
371	  } catch (err) {
372	    await fs.rm(staging, { recursive: true, force: true }).catch(() => undefined);
373	    await rmSidecarTmps();
374	    params.logger.warn(
375	      { err, to: params.newRoot },
376	      "Legacy GROK_HOME migration failed; continuing with empty home",
377	    );
378	    return false;
379	  }
380	}
