382	/**
383	 * Isolated GROK_HOME for Seawork gateway mode.
384	 *
385	 * Real ~/.grok often has auth.json from `grok login` (OIDC). When both OIDC
386	 * credentials and XAI_API_KEY exist, Grok 0.2.x still prefers Oidc and then
387	 * 401s against the Seawork LiteLLM gateway. Pointing GROK_HOME at a managed
388	 * dir with no auth.json forces API-key auth.
389	 */
390	export async function prepareManagedGrokHomeForGateway(params: {
391	  env: NodeJS.ProcessEnv;
392	  modelId?: string | null;
393	  logger: Logger;
394	}): Promise<string | null> {
395	  const gateway = resolveGrokGatewayEnv(params.env);
396	  if (!gateway.baseURL || !gateway.apiKey) {
397	    return null;
398	  }
399	
400	  const modelId = sanitizeGrokTomlModelId(params.modelId?.trim() || "gpt-5.4-mini-ops");
401	  const baseUrl = sanitizeGrokTomlHttpUrl(gateway.baseURL);
402	  // Home identity is the gateway, not the model: model is a session attribute
403	  // (grok resolves each session's model from its own record; config default only
404	  // seeds new sessions — verified against grok 1.0.5), so keying the home on
405	  // modelId made a UI model switch orphan all prior sessions on next resume
406	  // (issue #3842, session/load "Path not found").
407	  const fingerprint = grokHomeFingerprint(baseUrl);
408	  const seaworkHome =
409	    readEnvString(params.env, "SEAWORK_HOME") ??
410	    process.env.SEAWORK_HOME ??
411	    path.join(os.homedir(), ".seawork");
412	  const managedBase = path.join(seaworkHome, "managed-grok-home");
413	  const managedRoot = path.join(managedBase, fingerprint);
414	
415	  const work = async (): Promise<string> => {
416	    await fs.mkdir(managedRoot, { recursive: true });
417	    try {
418	      await migrateLegacyGrokHomes({
419	        managedBase,
420	        newRoot: managedRoot,
421	        baseUrl,
422	        logger: params.logger,
423	      });
424	    } catch (err) {
425	      // Migration failure must not block openSession — falling back to a new
426	      // empty session is the pre-fix behavior, not worse.
427	      params.logger.warn(
428	        { err, managedRoot },
429	        "Legacy GROK_HOME migration threw; continuing with empty home",
430	      );
431	    }
432	
433	    // Catalog miss → omit context_window; Grok falls back to built-in model defaults.
434	    const contextWindow = await getSeaworkModelContextWindow(modelId);
435	    const configToml = buildManagedGrokConfigToml({
436	      modelId,
437	      baseUrl,
438	      contextWindow,
439	    });
440	    const configPath = path.join(managedRoot, "config.toml");
441	    const tmpPath = `${configPath}.tmp-${process.pid}`;
442	    await fs.writeFile(tmpPath, configToml, "utf8");
443	    await fs.rename(tmpPath, configPath);
444	    params.logger.debug(
445	      { managedRoot, modelId, contextWindow: contextWindow ?? null },
446	      "Prepared managed GROK_HOME for Seawork gateway",
447	    );
448	    return managedRoot;
449	  };
450	
451	  const prev = managedHomePrepareChains.get(managedRoot) ?? Promise.resolve();
452	  const next = prev.catch(() => undefined).then(work);
453	  managedHomePrepareChains.set(managedRoot, next);
454	  try {
455	    return await next;
456	  } finally {
457	    if (managedHomePrepareChains.get(managedRoot) === next) {
458	      managedHomePrepareChains.delete(managedRoot);
459	    }
460	  }
461	}
