  try {
    return (await fs.stat(target)).mtimeMs;
  } catch {
    return null;
  }
}

/**
 * Recency used to pick the migration primary. grok 1.0.5 has no home-root
 * grok.db (the real index is sessions/session_search.sqlite), so fall back to
 * the index mtime — otherwise every candidate would tie at NEGATIVE_INFINITY
 * and the primary (and with it the merge winner + index source) would be
 * arbitrary.
 */
async function homeRecencyMs(candidate: LegacyHomeCandidate): Promise<number> {
  const db = await statMtimeMs(path.join(candidate.root, "grok.db"));
  if (db !== null) return db;
  const index = await statMtimeMs(
    path.join(candidate.root, "sessions", "session_search.sqlite"),
  );
  return index ?? Number.NEGATIVE_INFINITY;
}

async function sortByHomeRecencyDesc(
  candidates: LegacyHomeCandidate[],
): Promise<LegacyHomeCandidate[]> {
  const withMtime = await Promise.all(
    candidates.map(async (candidate) => ({
      ...candidate,
      mtime: await homeRecencyMs(candidate),
    })),
  );
  withMtime.sort((a, b) => b.mtime - a.mtime);
  return withMtime;
}"}

