  test("sessions rename failure (last step, core already landed) cleans up and retry succeeds", async () => {
    const managedBase = await makeTmp("grok-mig-sessfail-");
    dirs.push(managedBase);
    const newRoot = path.join(managedBase, "new-home");
    await writeLegacyHome(managedBase, "aaaaaaaaaaaa", {
      sessions: { "sess-1.json": "session" },
      grokDb: "db-bytes",
      extra: { "active_sessions.json": "[]" },
    });
    await fs.mkdir(newRoot, { recursive: true });

    const realRename = fs.rename.bind(fs);
    let failedOnce = false;
    const renameSpy = vi.spyOn(fs, "rename").mockImplementation(async (from, to) => {
      // sessions/ rename is the final completion-marker step; fail it once.
      if (String(to).endsWith("/sessions") && !failedOnce) {
        failedOnce = true;
        const err = new Error("simulated sessions rename failure") as NodeJS.ErrnoException;
        err.code = "EIO";
        throw err;
      }
      return realRename(from as string, to as string);
    });

    let migrated: boolean;
    try {
      migrated = await migrateLegacyGrokHomes({
        managedBase,
        newRoot,
        baseUrl: GATEWAY,
        logger,
      });
    } finally {
      renameSpy.mockRestore();
    }
    expect(migrated).toBe(false);
    // Core had already landed before the final rename — failure must clean it
    // up so a retry starts from a clean home (no orphan grok.db/active_sessions).
    expect(await exists(path.join(newRoot, "sessions"))).toBe(false);
    expect(await exists(path.join(newRoot, "grok.db"))).toBe(false);
    expect(await exists(path.join(newRoot, "active_sessions.json"))).toBe(false);
    const leftovers = (await fs.readdir(newRoot)).filter((n) => n.includes(".migrating-"));
    expect(leftovers).toEqual([]);

    const retried = await migrateLegacyGrokHomes({
      managedBase,
      newRoot,
      baseUrl: GATEWAY,
      logger,
    });
    expect(retried).toBe(true);
    expect(await fs.readFile(path.join(newRoot, "sessions", "sess-1.json"), "utf8")).toBe(
      "session",
    );
    expect(await fs.readFile(path.join(newRoot, "grok.db"), "utf8")).toBe("db-bytes");
  });
